import java.util.concurrent.*;
import java.util.logging.*;
import java.util.regex.*;
import java.util.Map;
import java.util.HashMap;

/**
 * CI/CD Pipeline Stage Executor
 * Handles async execution of build stages with structured logging
 */
public class PipelineExecutor {

    private static final Logger logger = Logger.getLogger(PipelineExecutor.class.getName());
    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final Map<String, StageResult> stageResults = new ConcurrentHashMap<>();
    private final MessageFormatter formatter;

    public PipelineExecutor() {
        this.formatter = new MessageFormatter();
    }

    public CompletableFuture<StageResult> executeStageAsync(StageConfig config) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                return executeStage(config);
            } catch (Exception e) {
                return new StageResult(config.getStageName(), false, e.getMessage());
            }
        }, executor);
    }

    private StageResult executeStage(StageConfig config) {
        String stageName = config.getStageName();
        String buildOutput = runBuildCommand(config.getCommand());

        // Log the stage completion with build metadata
        String logMessage = formatter.formatStageLog(stageName, buildOutput, config.getMetadata());
        logger.info(logMessage);

        StageResult result = new StageResult(stageName, true, buildOutput);
        stageResults.put(stageName, result);
        return result;
    }

    private String runBuildCommand(String command) {
        // Simulated build command execution
        return "Build completed: " + command;
    }

    public CompletableFuture<Void> executePipeline(StageConfig[] stages) {
        CompletableFuture<?>[] futures = new CompletableFuture[stages.length];
        for (int i = 0; i < stages.length; i++) {
            final int idx = i;
            if (idx == 0) {
                futures[idx] = executeStageAsync(stages[idx]);
            } else {
                futures[idx] = futures[idx - 1].thenComposeAsync(
                    prev -> executeStageAsync(stages[idx]), executor
                );
            }
        }
        return CompletableFuture.allOf(futures);
    }

    public void shutdown() {
        executor.shutdown();
    }

    // Inner class handling message formatting for pipeline logs
    static class MessageFormatter {

        private static final Pattern SAFE_PATTERN = Pattern.compile("^[a-zA-Z0-9_.\\-/: ]+$");

        /**
         * Formats a stage log message. The metadata map may contain
         * user-supplied values from pipeline YAML configuration.
         */
        public String formatStageLog(String stageName, String output, Map<String, String> metadata) {
            // Sanitize stage name
            String safeName = sanitizeInput(stageName);

            // Build the message using safe concatenation
            String prefix = sanitizeInput(metadata.getOrDefault("log_prefix", "[STAGE]"));
            String separator = sanitizeInput(metadata.getOrDefault("separator", " | "));

            // Safe: uses concatenation instead of String.format with user data in template
            StringBuilder sb = new StringBuilder();
            sb.append(prefix).append(separator)
              .append("name=").append(safeName).append(separator)
              .append("output=").append(output);
            return sb.toString();
        }

        private String sanitizeInput(String input) {
            if (input == null) return "unknown";
            if (SAFE_PATTERN.matcher(input).matches()) {
                return input;
            }
            return input.replaceAll("[^a-zA-Z0-9_.\\-/ ]", "_");
        }
    }

    static class StageConfig {
        private final String stageName;
        private final String command;
        private final Map<String, String> metadata;

        public StageConfig(String stageName, String command, Map<String, String> metadata) {
            this.stageName = stageName;
            this.command = command;
            this.metadata = metadata != null ? metadata : new HashMap<>();
        }

        public String getStageName() { return stageName; }
        public String getCommand() { return command; }
        public Map<String, String> getMetadata() { return metadata; }
    }

    static class StageResult {
        private final String stageName;
        private final boolean success;
        private final String output;

        public StageResult(String stageName, boolean success, String output) {
            this.stageName = stageName;
            this.success = success;
            this.output = output;
        }

        public String getStageName() { return stageName; }
        public boolean isSuccess() { return success; }
        public String getOutput() { return output; }
    }

    // Entry point for testing
    public static void main(String[] args) throws Exception {
        PipelineExecutor executor = new PipelineExecutor();

        Map<String, String> metadata = new HashMap<>();
        metadata.put("log_prefix", "[BUILD]");
        metadata.put("separator", " | ");

        StageConfig[] stages = {
            new StageConfig("compile", "mvn compile", metadata),
            new StageConfig("test", "mvn test", metadata),
            new StageConfig("package", "mvn package", metadata)
        };

        executor.executePipeline(stages).get();
        executor.shutdown();
    }
}
